"""Concise source registry; paraphrases, not copied articles. No canonical writes."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
S=[]
def add(id,title,url,locator,support,limit='Supports the stated clinical premise, not the producer visibility verdict or any unreviewed rewrite.'):
 S.append(dict(id=id,title=title,url=url,locator=locator,accessed='2026-09-12',support=support,limitations=limit))
add('lithium-label','DailyMed lithium carbonate prescribing information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=df756a61-baf2-758a-e053-2a95a90a10ff','Drug interactions: diuretics','Diuretic-associated sodium loss can reduce lithium clearance; hydrochlorothiazide is a listed example. This supports the interaction, not an invented medication chronology.')
add('kcl-label','Fresenius Kabi potassium chloride concentrate label','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fcd4f458-ce27-417e-9bb6-de1cc49d44b9','Dosage and administration; adverse reactions (including infusion discontinuation)','This product requires dilution. For potassium above2.5mEq/L its label specifies at most10mEq/hour and40mEq/L; site reactions include phlebitis/extravasation and warrant discontinuation/evaluation. Product-specific labeling does not establish a universal peripheral ward concentration limit.')
add('rch-pyloric','Royal Children’s Hospital: Pyloric stenosis','https://www.rch.org.au/clinicalguide/guideline_index/Pyloric_Stenosis/','Management: fluids table','Correct dehydration/electrolyte disturbances before surgery; add potassium only after urine output is adequate. The guideline supplies1–2mL/kg/hour as its adequacy criterion.')
add('chop-pyloric','Children’s Hospital of Philadelphia: Pyloric stenosis','https://www.chop.edu/conditions-diseases/pyloric-stenosis','Follow-up care after surgery','Feeds can begin a few hours after surgery, with small increasing amounts of Pedialyte or direct breastmilk/formula. A universal clear-liquid-first12–24-hour rule is not supported. Search-index text verified; direct open returned an error.')
add('lactulose-label','Kesin lactulose solution prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=163d5093-e35c-0bbf-e063-6294a90a803e&type=display','Adverse reactions; dosage and administration','Excessive dosing can cause diarrhea with fluid/electrolyte losses. Dose reduction and discontinuation for persistent diarrhea contradict a universal never-stop instruction; clinician-directed adjustment remains required.')
add('spironolactone-label','DailyMed spironolactone prescribing information','https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=90668e5a-0c0d-4941-94cf-8b2fba410ed7','Mechanism of action','Aldosterone antagonism promotes sodium/water excretion while retaining potassium; it does not support the item’s claim that spironolactone predictably worsens potassium depletion.')
add('morphine-label','DailyMed morphine sulfate tablets prescribing information','https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=300b6afd-bac8-32ca-e063-6294a90a12a7','12.1–12.2 pharmacology','Morphine acts at opioid receptors and can depress respiration, including brainstem response to carbon dioxide. This label does not establish two exclusive dyspnea-mechanism distractors or guarantee absence of respiratory adverse effects.')
add('palliative-dyspnea','Scottish Palliative Care Guidelines: Breathlessness','https://www.rightdecisions.scot.nhs.uk/scottish-palliative-care-guidelines/symptom-management/breathlessness/?searchTerm=ipratropium','Medication management of ongoing breathlessness','Guidance describes carefully titrated opioids for refractory breathlessness, including heart-failure contexts; dosing must consider prior exposure and renal function. Used to ground a replacement symptom/monitoring construct, not import a dose.')
add('advance-directives','NIA: Advance care planning and advance directives','https://www.nia.nih.gov/health/advance-care-planning/advance-care-planning-advance-directives-health-care','Living will versus durable power of attorney','A living will specifies treatment preferences; a durable healthcare power of attorney names a proxy. Merely documenting an advance directive with a daughter present does not establish her appointment.')
add('hipaa-family','HHS: Communication with family and others involved in care','https://www.hhs.gov/hipaa/for-professionals/faq/2087/does-hipaa-allow-a-health-care-provider-to-communicate-with-a-patients-family-friends-or-other-persons-who-are-involved-in-the-patient-care.html','45CFR164.510(b) explanation','With a capable patient present, relevant information may be shared if the patient agrees or does not object; professional judgment and best-interest provisions also exist. Emergency-contact status is not unlimited disclosure authority. A proposed permission-based response is one valid path, not the sole legal path.')
add('aspiration','MedlinePlus: Poisoning first aid','https://medlineplus.gov/ency/article/007579.htm','First aid','Assess airway/breathing and protect against aspiration; side positioning during vomiting supports the airway-priority proposition. This does not replace emergency clinical assessment.')
add('extrip','EXTRIP Workgroup lithium recommendations','https://www.extrip-workgroup.org/lithium','Indications for extracorporeal treatment','Decreased consciousness, seizures or life-threatening dysrhythmias can justify extracorporeal treatment independent of lithium concentration. The systematic recommendation is also indexed at https://pubmed.ncbi.nlm.nih.gov/25583292/; clinical evidence quality is low.')
add('idsa-fever','ASCO/IDSA outpatient fever and neutropenia guideline2018','https://www.idsociety.org/globalassets/idsa/practice-guidelines/outpatient-management-of-fever-and-neutropenia.pdf','Definitions, journal page1446','Published oral fever thresholds pair38.3°C with101°F for one reading and38.0°C with100.4°F sustained one hour. Preserve the published pairing for the case’s call rule; distinguish clinical thresholds from ordinary measured-temperature conversions.')
add('endotext-storm','Endotext: Treatment of thyroid storm','https://www.ncbi.nlm.nih.gov/books/NBK278927/table/thyroid-storm.T.treatment_of_thyroid_sto/','Table3','The specific dependency is iodine after the first thionamide dose (one hour); glucocorticoids are part of concurrent treatment. A forced four-drug total order placing STAT steroid last is not established.')
add('nice-dehydration','NICE CG84: Gastroenteritis in children under5','https://www.nice.org.uk/guidance/cg84/chapter/Recommendations','Table1;1.3;1.7–1.8','Assess dehydration using the full clinical picture; worsening responsiveness and perfusion are important red flags. Oral rehydration is appropriate in many dehydrated children. Isolated absent tears does not itself establish shock or exclusion of oral rehydration.')
add('nice-nutrition','NICE CG32: Adult nutrition support','https://www.nice.org.uk/guidance/cg32/chapter/Recommendations','1.7.1 and1.8.1–1.8.2; monitoring tables','Unsafe/inadequate oral intake with a functional accessible gut can support enteral tube feeding. PN indications concern inability to meet needs safely by oral/enteral routes or gut dysfunction. Inability to swallow alone does not prove that all enteral feeding is impossible.')
add('sps-label','Sodium polystyrene sulfonate prescribing information','https://dailymed.nlm.nih.gov/dailymed/getFile.cfm?setid=2017bfbe-cda8-46f1-b4f1-9c086c3249a9&type=pdf','5.4 Risk of aspiration','Altered consciousness, impaired gag reflex and regurgitation increase aspiration risk. This supports querying oral resin in the documented lethargic patient without inventing current vomiting.')
add('cdc-lead','CDC: Recommended actions based on blood lead level','https://www.cdc.gov/lead-prevention/hcp/clinical-guidance/index.html','Confirmed venous BLL; tables1–2','A confirmed venous10–19µg/dL result follows an early1–3-month retesting schedule with exposure/nutrition/development management. Capillary confirmation follows a different schedule. The≥45µg/dL lane calls for specialist-directed chelation consideration.')
add('acog-preeclampsia','ACOG: Preeclampsia and high blood pressure','https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy','Severe features; HELLP definition','Severe blood pressure and neurologic/organ features can signal preeclampsia, including postpartum. HELLP denotes hemolysis, elevated liver enzymes and low platelets; a subset of those findings is not the complete triad.')
add('ruxolitinib-label','Jakafi prescribing information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1c82580-87ae-11e0-bc84-0002a5d5c51b','Acute GVHD indication and safety monitoring;14.3','Ruxolitinib is used for steroid-refractory acute GVHD with hematologic/infection monitoring. Explicit symptom/laboratory direction can be interpreted without extrapolating an8-hour stool amount to a24-hour total. No new dose is proposed.')
add('clozapine-label','DailyMed clozapine prescribing information','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=883b5d43-0339-7dc1-f775-93791fb9b978','Neutropenia management;5.5 myocarditis','Suspected myocarditis warrants discontinuation and cardiac evaluation; it commonly occurs early in treatment. ANC/fever management must follow the applicable population-specific labeling and the case’s stated hold protocol. Current label is used without relying on obsolete REMS assumptions.')
add('kdigo-aki','KDIGO2012 AKI guideline','https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf','Stage-based management Figure4;2.3','AKI care includes continued creatinine, urine-output and hemodynamic assessment. Improved vitals do not discharge monitoring needs. KDIGO’s live AKI page states the2026 revision is preparing for publication after public review; a draft is not substituted for final guidance.')
add('idsa-crbsi','SCCM/IDSA: New fever in critically ill adults','https://www.idsociety.org/practice-guideline/new-fever-in-critically-ill-patients/','IV: Blood cultures','Simultaneous central and peripheral cultures support differential time-to-positivity assessment; the same organism appearing centrally at least two hours earlier supports a catheter source. An unspecified earlier bottle alone does not establish that criterion.')
add('aha-tachycardia','AHA: Tachycardia','https://www.heart.org/en/health-topics/arrhythmia/about-arrhythmia/tachycardia--fast-heart-rate','Quick facts','Resting adult tachycardia is above 100 beats/minute. A rate of 92 alone does not support calling the rhythm sinus tachycardia.')
add('aha-opioid','AHA2025 special circumstances of resuscitation','https://www.ahajournals.org/doi/pdf/10.1161/CIR.0000000000001380','Opioid poisoning; page S652','Support airway and ventilation promptly; naloxone complements resuscitation and may require repeated doses. The recommendations do not establish a rigid total ordering of concurrent team tasks.')
add('aha-arrest','AHA2025 Adult Advanced Life Support','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support','10: Vasopressor medications in cardiac arrest; cardiac-arrest algorithm','Prioritize CPR and defibrillation in shockable arrest; epinephrine is reasonable after initial defibrillation attempts fail. Preparing medication can occur alongside other team work; preparation is not administration.')
add('sepsis-guideline','Surviving Sepsis Campaign2026 adult guideline','https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026','Blood culture; antibiotic initiation; resuscitation','Collect blood cultures as soon as possible, ideally before antimicrobials. Sepsis/shock requires immediate treatment and resuscitation; a rigid cultures-first key must not license avoidable treatment delay or treat a single marker as exclusion of infection.')
add('ukka-hyperk','UKKA acute hyperkalaemia guideline, updated July2026','https://www.ukkidney.org/sites/default/files/documents/FINAL%20VERSION%20-%20UKKA%20CLINICAL%20PRACTICE%20GUIDELINE%20-%20MANAGEMENT%20OF%20HYPERKALAEMIA%20IN%20ADULTS%20-%20UPDATED%20JULY%202026_0.pdf','Guideline16.6.3; pages110–112; update summary','Resin therapy has limitations in acute hyperkalaemia and is not a substitute for immediate cardiac protection and potassium shifting. UK recommendations distinguish CPS from US SPS; the SPS label independently grounds aspiration risk. No UK dosing protocol is imported into the US case.')
add('hhs-breach','HHS: Breach notification rule','https://www.hhs.gov/hipaa/for-professionals/breach-notification/index.html','Risk assessment; administrative requirements and burden of proof','Breach response requires assessment, mitigation and documentation under institutional procedures. This page does not authorize a bedside nurse to permanently delete potential evidence before privacy review; that unprovided procedure remains a review hold.')
add('hhs-workers-comp','HHS: Workers compensation disclosures','https://www.hhs.gov/hipaa/for-professionals/privacy/guidance/disclosures-workers-compensation/index.html','45CFR164.512(l)','Workers-compensation disclosures have legally defined permitted pathways; a general no-disclosure-to-employer claim cannot replace assessment of authority and scope.')
add('hhs-incidental','HHS: Incidental uses and disclosures','https://www.hhs.gov/hipaa/for-professionals/privacy/guidance/incidental-uses-and-disclosures/index.html','General provision; reasonable safeguards','A limited incidental disclosure can be permitted when the underlying communication is permitted and reasonable safeguards are applied. Overhearing is not automatically a violation independent of context.')
add('aphasia-capacity','Aphasia Institute: Capacity and decision making tools','https://www.aphasia.ca/health-care-providers/resources-and-tools/capacity-and-decision-making-tools/','CACE introduction','Communication support can help people with aphasia understand and express decisions. Aphasia alone does not establish incapacity; an assessment and authorized surrogate relationship cannot be inferred from inability to speak.')
add('ama-consent','AMA Code of Medical Ethics: Informed consent','https://code-medical-ethics.ama-assn.org/ethics-opinions/informed-consent','Opinion2.1.1','Assess understanding, implications and ability to make a voluntary decision; communicate options and document consent. Emergency exceptions and surrogate decisions depend on their specified conditions, not merely a signature or a family presence.')
add('hhs-language','HHS: Family or friend as interpreter','https://www.hhs.gov/civil-rights/for-individuals/faqs/may-an-lep-person-use-a-family-member-as-an-interpreter/709/index.html','Answer','For important decisions, interpretation must be accurate, effective and impartial. Family may lack competence or have conflicting interests. The provider must offer competent services at no cost when needed for meaningful access; a patient can decline the provided interpreter.')
add('acc-shock','ACC: Cardiogenic shock and mechanical circulatory support2025 review','https://www.acc.org/latest-in-cardiology/articles/2026/08/03/15/28/cardiogenic-shock-and-mechanical-circulatory-support','2025 expert consensus overview','Hemodynamic assessment guides vasoactive support and escalation; the consensus favors norepinephrine as first-line vasopressor. Choice of inotrope/vasopressor depends on the clinical profile; a universal immediate-inotrope rule needs review.')
add('aspen-refeeding','ASPEN Consensus Recommendations for Refeeding Syndrome','https://pubmed.ncbi.nlm.nih.gov/32115791','Abstract diagnostic criteria; DOI10.1002/ncp.10474','Phosphorus, potassium and/or magnesium decline and associated organ dysfunction within five days of calorie reintroduction support refeeding syndrome. A concurrent infectious process is not excluded by that diagnosis. Detailed treatment doses require full guideline review; none are proposed here.')
add('ahrq-sbar','AHRQ TeamSTEPPS: SBAR','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/sbar.html','Using SBAR effectively','Structured handoff includes current situation, pertinent background, assessment and a request/recommendation. Case-specific data must be actually available at the selected boundary; later completed calls cannot supply those facts retroactively.')
add('ahrq-teachback','AHRQ TeamSTEPPS: Teach-back','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/teachback.html','Tool description','Ask the patient or caregiver to explain needed information/actions in their own words. A chart title announcing success/failure can give away the interpretation being tested.')
add('cdc-cauti','CDC: CAUTI summary of recommendations','https://www.cdc.gov/infection-control/hcp/cauti/summary-of-recommendations.html','Appropriate urinary-catheter use; Table2','Acute urinary retention can be an indication for catheterization; unnecessary use should be avoided. A patient-specific retention/fall-risk assessment supports assisted care, not a universal catheter-first or walking-toilet rule.')
add('cdc-contact','CDC: Transmission-based precautions','https://cdc.gov/infection-control/hcp/basics/transmission-based-precautions.html','Contact precautions','Gown/gloves are used for interactions involving contact with the patient/environment, with appropriate removal and hand hygiene. Case-specific caregiver knowledge must be assessed rather than inferred from a later demonstration.')
add('pressure-guideline','International Pressure Injury Guideline: Heels','https://www.internationalguideline.com/heels','Heel offloading implementation and monitoring','Select and check heel-offloading devices; periodically remove them to assess skin, perfusion and swelling. A shifted device can create new pressure even when a heel remains intact; the current skin/device assessment matters.')
add('nia-dementia-safety','NIA: Caregiver worksheets','https://www.nia.nih.gov/health/caregiving/caregiver-worksheets','Coordinating responsibilities; home safety; medication management','Care planning includes shared caregiving responsibilities, home safety and medication oversight. An individual caregiver’s resource needs still require the actual case assessment, not generic dementia facts.')
add('samhsa-safe-t','SAMHSA SAFE-T','https://www.samhsa.gov/resource/dbhis/safe-t-pocket-card-suicide-assessment-five-step-evaluation-triage-safe-t-clinicians','Five-step assessment; linked pocket card','Suicide assessment includes direct inquiry about ideation, plans, behavior and intent, risk/protective factors, intervention and documentation. A denial of current thoughts is not documentation of a separately asked plan/intent assessment.')
add('samhsa-overdose','SAMHSA: Opioid overdose prevention and reversal','https://www.samhsa.gov/substance-use/treatment/overdose-prevention','Immediate response; causes','Emergency response, breathing/resuscitation support and an available opioid reversal medicine are essential. Extra opioid doses and combinations with sedatives/alcohol increase risk; naloxone access does not replace treatment continuity and monitoring.')
add('jointcommission-suicide','Joint Commission: Suicide risk reduction','https://www.jointcommission.org/en-us/knowledge-library/suicide-prevention','Nonpsychiatric units in general hospitals','Mitigate patient-specific environmental risks, use one-to-one observation where indicated and remove potential self-harm objects when this does not undermine medical care. The case must establish which equipment is removable and how essential care continues.')
add('poison-help','National Capital Poison Center: First aid','https://www.poison.org/first-aid-for-poisonings','Emergency signs; swallowed poisons','Collapse, seizure, breathing difficulty or inability to awaken requires emergency services. Other exposures merit immediate poison-expert advice; do not induce vomiting. This supports clear triage wording without generating a new pediatric drug dose.')
add('buprenorphine-label','Buprenorphine/naloxone sublingual film label','https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=300ae3d0-464c-d0be-e063-6294a90a7f9d','2.4 Maintenance','The described16mg/4mg maintenance target is a single daily dose with individualized prescribing. A morning dose already taken plus an unexplained second full evening dose conflicts with the case’s once-daily regimen; reconcile the medication timeline, not invent a new regimen.')
add('alteplase-label','Genentech Activase prescribing information','https://www.gene.com/gene/products/information/pdf/activase-prescribing.pdf','2.1 Acute ischemic stroke','The label identifies pretreatment INR greater than1.7 as a reason to discontinue treatment and requires blood-pressure monitoring/control. The case’s institutional rule remains a necessary visible input where the question explicitly asks to apply that rule.')
add('nicardipine-label','DailyMed nicardipine hydrochloride injection','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d0070638-bea5-413a-8658-4c752c6104f5','2.2 Monitoring','Monitor blood pressure and heart rate continuously during infusion and avoid excessive/rapid pressure reduction. A later achieved pressure or completed medication preparation cannot be used as an earlier nursing decision cue.')
add('sitc-ici','SITC immune-checkpoint adverse-event guideline2021','https://pmc.ncbi.nlm.nih.gov/articles/PMC8237720/','Hepatitis recommendations; corroborating SITC2017 diagnostic evaluation','Checkpoint therapy can cause colitis/hepatitis, but competing causes of liver injury require evaluation. The2017 SITC consensus explicitly includes viral infection, alcohol, medications and cancer progression: https://pmc.ncbi.nlm.nih.gov/articles/PMC5697162/. Existing liver metastases cannot be silently excluded.')
add('nice-head-injury','NICE NG232: Head injury','https://www.nice.org.uk/guidance/NG232/chapter/recommendations','Referral; CT criteria; deterioration and transfer','New neurological deficits, reduced consciousness and concerning vomiting after injury require prompt evaluation/escalation. The proposal uses observed post-fall findings; it does not introduce a new local transport or CT protocol.')
add('hip-fracture','NHS: Broken hip','https://www.nhs.uk/conditions/broken-hip/','Symptoms and emergency advice','Hip/groin pain with an abnormally angled or shortened leg after a fall raises fracture concern and needs hospital assessment. Such findings should not be treated as merely routine follow-up or resolved by walking the patient.')
add('nice-mscc','NICE NG234: Metastatic spinal cord compression','https://www.nice.org.uk/guidance/ng234/chapter/Recommendations','1.3 recognition;1.8 corticosteroid therapy','Cancer with new neurological or bladder dysfunction can indicate a spinal cord emergency; prompt specialist management and corticosteroids are recommended in the appropriate setting. The case’s newly prescribed IV medication is a real stage-specific input; a bladder scan after no void is not a postvoid residual.')
add('taco','Australian Red Cross Lifeblood: TACO','https://www.lifeblood.com.au/health-professionals/clinical-practice/adverse-events/TACO','Diagnosis and management','Post-transfusion respiratory deterioration with hypertension, positive fluid balance and cardiac involvement supports circulatory overload. Baseline risk factors alone do not establish the actual reaction; consider the current cluster and competing transfusion reactions.')
# All sources are bounded support, not independent certification.
def write():
 assert len({x['id'] for x in S})==len(S)
 (ROOT/'phase-a/sources.json').write_text(json.dumps(S,ensure_ascii=False,indent=2)+'\n')
 print(f'Wrote {len(S)} source records; registry completeness is checked separately.')
if __name__=='__main__':write()
